    d.querySelector('form').onsubmit = async e => { e.preventDefault(); await conBoton(e.target.querySelector('button'), async () => { const r = await api('registro', { ...form(e.target), ...origen() }); guardarTok(r.token); d.remove(); location.hash = '#/inicio'; render(); toast('🎉 ¡Bienvenido(a)! Crea tu primera aula'); }); };
