  document.addEventListener('click', async e => { const a = e.target.closest('[data-apush]'), n = e.target.closest('[data-npush]'); if (n) { LS.set('pt_push', 'no'); n.closest('.aviso-push').remove(); } if (a) { try { await activarPush(); a.closest('.aviso-push').remove(); toast('🔔 ¡Avisos activados!'); } catch (er) { toast('⚠️ ' + er.message); } } });

